//#region 🖥️FrameworkOsPlaygroundDev
/** 🔌️ Local dev-time asset server port for wgpu Trunk/native playgrounds (Trunk forwards
 * route-scoped requests — e.g. `/osm`, `/vt`, `/dem` — here; driven by each playground's declared
 * `[[package.metadata.semio.assets]]` rows, not any one app's routes). */
export const SEMIO_ASSET_SERVER_PORT = 6141;

/** 🔌️ Process env for the absolute asset server URL base (native-bin wgpu route-relative fetches). */
export const SEMIO_ASSET_BASE_URL_ENV = "SEMIO_ASSET_BASE_URL";

/** 🔌️ Resolves the default dev port for a given catalog variant and renderer. */
export function frameworkOsPlaygroundDefaultPort(catalog: readonly PlaygroundVariant[], variant: string, renderer: string): number {
  const row = catalog.find((r) => r.variant === variant);
  if (!row) return 6066;
  return renderer === "wgpu" ? row.ports.wgpu : row.ports.react;
}

/** 🎯️ Resolves `bun ./📜️script.ts dev …` segments to a framework OS plugin filter via the catalog. */
export function resolveFrameworkOsPlaygroundPlugin(catalog: readonly PlaygroundVariant[], segments: readonly string[]): { readonly plugin: string; readonly rest: readonly string[] } | null {
  if (segments.length === 0) return null;
  for (let len = segments.length; len >= 1; len--) {
    const alias = segments.slice(0, len).join(" ");
    const row = catalog.find((r) => r.variant === alias || r.aliases.includes(alias));
    if (row) {
      return { plugin: row.variant, rest: segments.slice(len) };
    }
  }
  return null;
}

/** 🧊️ Env for `@semio-tech/framework-os-dev:dev` with a plugin filter and the renderer an
 * explicit `SEMIO_RENDERER` (launch row, `extra`) selects — wgpu only as the unset default. The value
 * picks the `dev-<variant>-<renderer>-<profile>` target in `resolveNxInvocation`, so a react launch
 * row reaches Vite and never the wgpu browser server. */
export function frameworkOsPlaygroundDevEnv(catalog: readonly PlaygroundVariant[], plugin: string, extra: Partial<NodeJS.ProcessEnv> = {}, env: NodeJS.ProcessEnv = process.env): NodeJS.ProcessEnv {
  const renderer = extra.SEMIO_RENDERER ?? env.SEMIO_RENDERER ?? "wgpu";
  const defaultPort = frameworkOsPlaygroundDefaultPort(catalog, plugin, renderer);
  const portVal = extra.S_OS_PORT || env.S_OS_PORT || String(defaultPort);
  return devToolingEnv({
    SEMIO_PLUGIN: plugin,
    ...extra,
    SEMIO_RENDERER: renderer,
    S_OS_PORT: portVal,
  });
}
//#endregion 🖥️FrameworkOsPlaygroundDev

/** 🧰️Play/vite dev env with optional file-watcher polling defaults. Polling only makes sense where
 * native filesystem events don't reach the watcher (bind-mounted devcontainers) — on native macOS/
 * Windows/Linux it just burns CPU/RSS across every spawned dev server for no benefit. An explicit
 * `WATCHPACK_POLLING` always wins as a manual override in either direction. */
export function playPollingEnv(extra: Partial<NodeJS.ProcessEnv> = {}): NodeJS.ProcessEnv {
  const pollingDefault = process.env.WATCHPACK_POLLING !== undefined ? {} : process.env.DEVCONTAINER === "true" ? { WATCHPACK_POLLING: "true", CHOKIDAR_USEPOLLING: "true" } : {};
  return devToolingEnv({
    ...pollingDefault,
    ...extra,
  });
}

/** 🔒️ Parses optional `example <id>` argv prefix for playground play scripts. */
export function consumePlaygroundExampleArgv(segments: string[], resolveExampleId: (slug: string) => string | undefined): { readonly segments: string[]; readonly exampleEnv: NodeJS.ProcessEnv } {
  if (segments[0] !== "example" || !segments[1]) {
    return { segments, exampleEnv: {} };
  }
  const exampleId = resolveExampleId(segments[1]);
  if (!exampleId) {
    console.error(`[play] unknown example ${JSON.stringify(segments[1])}`);
    process.exit(1);
  }
  return {
    segments: segments.slice(2),
    exampleEnv: { PLAYGROUND_LOCKED_EXAMPLE_ID: exampleId },
  };
}

/** ▶️Playwright test run in bundle directory; browsers land in the shared cache root. */
export function runPlaywright(bundleRoot: string, config: string, segments: string[] = []): void {
  runBunx(["playwright", "test", "--config", config, ...segments], bundleRoot, repoToolCacheEnv(findWorkspaceRoot(bundleRoot), playPollingEnv()));
}

/** 🔌️ True when host:port already accepts TCP (existing dev server). */
export function isDevPortInUse(host: string, port: number): boolean {
  const probe = `
import { createConnection } from "node:net";
const socket = createConnection({ host: ${JSON.stringify(host)}, port: ${port} });
socket.setTimeout(300);
socket.once("connect", () => process.exit(0));
socket.once("timeout", () => process.exit(1));
socket.once("error", () => process.exit(1));
`;
  const result = spawnSync(process.execPath, ["--input-type=module", "-e", probe], { timeout: 500 });
  return result.status === 0;
}

/** 🌐️ Loopback URL for a dev server bound to `host`/`port`. */
export function devServerUrl(host: string, port: number): string {
  const probeHost = host === "0.0.0.0" ? "127.0.0.1" : host;
  return `http://${probeHost}:${port}/`;
}

/** 🧊️ Legacy trunk entry paths still seen on long-running dev servers. */
export const WGPU_DEV_LEGACY_ENTRY_PATH = "/renderer-modules/wgpu/";

/** 🧊️ Play URL for a wgpu trunk entry path and plugin filter. */
export function wgpuDevPlayUrl(host: string, port: number, plugin: string, entryPath = "/"): string {
  const probeHost = host === "0.0.0.0" ? "127.0.0.1" : host;
  const base = entryPath.endsWith("/") ? entryPath : `${entryPath}/`;
  return `http://${probeHost}:${port}${base}?plugin=${encodeURIComponent(plugin)}`;
}

/** 🧊️ Probes which wgpu trunk entry path responds on `port`, if any. */
export function probeWgpuDevPort(host: string, port: number): { entryPath: string } | null {
  const probeHost = host === "0.0.0.0" ? "127.0.0.1" : host;
  for (const entryPath of ["/", WGPU_DEV_LEGACY_ENTRY_PATH] as const) {
    const url = `http://${probeHost}:${port}${entryPath}`;
    const probe = `const res = await fetch(${JSON.stringify(url)}, { signal: AbortSignal.timeout(2000) });
process.exit(res.ok ? 0 : 1);`;
    const result = spawnSync(process.execPath, ["--input-type=module", "-e", probe], { timeout: 3000 });
    if (result.status === 0) return { entryPath };
  }
  return null;
}

/** 🛑️ Stops a trunk listener on `port` when it is the sole occupant. */
export function stopTrunkDevPort(port: number): boolean {
  const occupant = describeDevPortOccupant(port);
  if (!occupant?.startsWith("trunk")) return false;
  const pid = Number(occupant.match(/PID (\d+)/)?.[1]);
  if (!Number.isFinite(pid)) return false;
  try {
    process.kill(pid, "SIGTERM");
    return true;
  } catch {
    return false;
  }
}

/** 🎯️ Reads `import.meta.env.PLAYGROUND_APP_KIND` baked into a running playground dev server. */
export function devServerPlayEntry(host: string, port: number): string | undefined {
  const url = `${devServerUrl(host, port)}index.ts`;
  const probe = `const res = await fetch(${JSON.stringify(url)}, { signal: AbortSignal.timeout(2000) });
if (!res.ok) process.exit(1);
const text = await res.text();
const match = text.match(/PLAYGROUND_APP_KIND\\":\\s*\\"([^\\"]+)\\"/);
process.stdout.write(match?.[1] ?? "");
`;
  const result = spawnSync(process.execPath, ["--input-type=module", "-e", probe], { encoding: "utf8", timeout: 3000 });
  const entry = result.stdout?.trim();
  return entry || undefined;
}

/** 🔎️ Best-effort description of the process listening on `port` (Unix/macOS/Linux). */
export function describeDevPortOccupant(port: number): string | undefined {
  if (process.platform === "win32") return undefined;
  const result = spawnSync("lsof", ["-nP", `-iTCP:${port}`, "-sTCP:LISTEN"], { encoding: "utf8" });
  const line = result.stdout
    ?.trim()
    .split("\n")
    .find((row, index) => index > 0 && row.trim().length > 0);
  if (!line) return undefined;
  const parts = line.trim().split(/\s+/);
  return parts.length >= 2 ? `${parts[0]} (PID ${parts[1]})` : line.trim();
}

/** ♻️ True when an HTTP server on `port` already responds successfully (reuse existing dev). */
export function canReuseDevPort(host: string, port: number, expectedPlayEntry?: string): boolean {
  const url = devServerUrl(host, port);
  const probe = `const res = await fetch(${JSON.stringify(url)}, { signal: AbortSignal.timeout(2000) });
process.exit(res.ok ? 0 : 1);`;
  const result = spawnSync(process.execPath, ["--input-type=module", "-e", probe], { timeout: 3000 });
  if (result.status !== 0) return false;
  if (!expectedPlayEntry) return true;
  return devServerPlayEntry(host, port) === expectedPlayEntry;
}

/** 🔌️ First free TCP port at or after `preferredPort` (up to `maxAttempts`), skipping `skipPorts`. */
export function resolveDevPort(host: string, preferredPort: number, maxAttempts = 20, skipPorts: ReadonlySet<number> = new Set()): number {
  for (let offset = 0; offset < maxAttempts; offset++) {
    const port = preferredPort + offset;
    if (skipPorts.has(port)) continue;
    if (!isDevPortInUse(host, port)) return port;
  }
  console.error(`[dev] No free port found in range ${preferredPort}-${preferredPort + maxAttempts - 1}.`);
  process.exit(1);
}

/** ▶️Vite dev via `bunx` with an explicitly owned configuration source. */
export function runViteBunxDev(
  bundleRoot: string,
  segments: string[],
  opts: {
    config: string;
    portEnv?: string;
    defaultPort?: string;
    clearViteCache?: boolean;
    strictPort?: boolean;
    /** When true, bind only `defaultPort` / env — never bump into another playground port. */
    fixedPort?: boolean;
    reservedPorts?: ReadonlySet<number>;
    env?: NodeJS.ProcessEnv;
    /** When set with `fixedPort`, only reuse an existing listener serving this play entry. */
    expectedPlayEntry?: string;
  },
): Promise<void> {
  const host = process.env.DEVCONTAINER === "true" ? "0.0.0.0" : "127.0.0.1";
  const preferredPort = Number(process.env[opts.portEnv ?? "VITE_PORT"] ?? opts.defaultPort ?? "5173");
  const spawnEnv = playPollingEnv(opts.env);
  if (opts.fixedPort && isDevPortInUse(host, preferredPort)) {
    const url = devServerUrl(host, preferredPort);
    if (canReuseDevPort(host, preferredPort, opts.expectedPlayEntry)) {
      console.log(`[dev] Port ${preferredPort} is already in use — dev server appears to be running at ${url}`);
      return Promise.resolve();
    }
    const occupant = describeDevPortOccupant(preferredPort);
    const servedEntry = devServerPlayEntry(host, preferredPort);
    if (servedEntry && opts.expectedPlayEntry && servedEntry !== opts.expectedPlayEntry) {
      console.error(`[dev] Port ${preferredPort} is serving play entry "${servedEntry}" but "${opts.expectedPlayEntry}" was requested. Stop that process or set ${opts.portEnv ?? "VITE_PORT"}.`);
      process.exit(1);
    }
    console.error(`[dev] Port ${preferredPort} is already in use${occupant ? ` by ${occupant}` : ""}. Stop that process or set ${opts.portEnv ?? "VITE_PORT"}.`);
    process.exit(1);
  }
  const port = (() => {
    if (opts.fixedPort) {
      return preferredPort;
    }
    const skip = opts.reservedPorts ?? new Set<number>();
    const resolved = resolveDevPort(host, preferredPort, 20, skip);
    if (resolved !== preferredPort) {
      console.warn(`[dev] Port ${preferredPort} is already in use — starting on ${resolved} instead.`);
      if (opts.portEnv) process.env[opts.portEnv] = String(resolved);
    }
    return resolved;
  })();
  if (opts.clearViteCache) {
    const viteCache = join(bundleRoot, "node_modules", ".vite");
    if (existsSync(viteCache)) rmSync(viteCache, { recursive: true, force: true });
  }
  const wantStrictPort = opts.strictPort ?? true;
  const viteArgs = ["vite", "--config", opts.config, "--host", host, "--port", String(port)];
  if (wantStrictPort && !segments.includes("--strictPort") && !segments.includes("--no-strictPort")) {
    viteArgs.push("--strictPort");
  }
  return spawnBunx([...viteArgs, ...segments], bundleRoot, spawnEnv);
}

/** ▶️Vite dev via `bunx` without a fixed config path (extra args only). */
export function runViteBunxDevPlain(bundleRoot: string, segments: string[]): void {
  const host = process.env.DEVCONTAINER === "true" ? "0.0.0.0" : "127.0.0.1";
  spawnBunx(["vite", "--host", host, ...segments], bundleRoot, playPollingEnv());
}

/** 🦀️Runs `cargo` through [[runCmd]] — on POSIX via the cargo relay, which pipes and forwards its output ([[cargoStreamingStatus]]). */
export function runCargo(args: string[], cwd: string, env: NodeJS.ProcessEnv = process.env): void {
  runCmd("cargo", selectedCargoArguments(getWorkspaceRoot(), args), { cwd, env });
}


/** 📦️ Resolves an explicitly provisioned binding generator on every supported host. */
export function resolveWasmBindgenBin(repoRoot = getWorkspaceRoot(), env: NodeJS.ProcessEnv = process.env): string {
  const version = wasmBindgenVersion(readFileSync(join(repoRoot, "Cargo.lock"), "utf8"));
  if (env.WASM_BINDGEN_VERSION && env.WASM_BINDGEN_VERSION !== version) throw new Error("WASM_BINDGEN_VERSION disagrees with Cargo.lock");
  const runtime = (globalThis as { readonly Bun?: unknown }).Bun;
  const which = typeof runtime === "object" && runtime !== null ? (runtime as { readonly which?: unknown }).which : undefined;
  if (!env.SEMIO_WASM_BINDGEN_BIN && typeof which !== "function") throw new Error("wasm-bindgen resolution requires Bun.which.");
  const command = env.SEMIO_WASM_BINDGEN_BIN
    ? resolve(repoRoot, env.SEMIO_WASM_BINDGEN_BIN)
    : (which as (name: string, options: { readonly PATH?: string }) => string | null)("wasm-bindgen", { PATH: env.PATH });
  if (!command) throw new Error("Run bun nx run workspace:deps-wasm to provision wasm-bindgen");
  const probe = runProbe(command, ["--version"], { env });
  if (probe.status !== 0 || probe.stdout.trim() !== `wasm-bindgen ${version}`) throw new Error(`wasm-bindgen ${version} is required; run bun nx run workspace:deps-wasm`);
  return command;
}

/** 🏗️ Shares the browser compiler environment across crates; Cargo's own config governs where it writes, no private default. */
export function wasmBuildEnvironment(repoRoot: string, env: NodeJS.ProcessEnv = process.env): NodeJS.ProcessEnv {
  return { ...env };
}

/** 🧭️ Makes wasm-pack resolve the selected optimizer while preserving the pinned binding generator. */
export function wasmPackEnvironment(repoRoot: string, bindgen: string, env: NodeJS.ProcessEnv): NodeJS.ProcessEnv {
  const optimizer = env.SEMIO_WASM_OPT_BIN ? resolve(repoRoot, env.SEMIO_WASM_OPT_BIN) : preparedBinaryen(repoRoot);
  if (optimizer && basename(optimizer) !== (process.platform === "win32" ? "wasm-opt.exe" : "wasm-opt")) throw new Error("SEMIO_WASM_OPT_BIN must name a wasm-opt executable");
  const environment = { ...env, PATH: [dirname(bindgen), ...(optimizer ? [dirname(optimizer)] : []), env.PATH].filter(Boolean).join(process.platform === "win32" ? ";" : ":") };
  if (optimizer) {
    const selected = Bun.which("wasm-opt", { PATH: environment.PATH });
    if (!selected || realpathSync(selected) !== realpathSync(optimizer)) throw new Error("Selected wasm-opt is missing or shadowed by another tool");
  }
  return environment;
}

/** 🧭️ Authors selected repository tools and compiler storage for one browser source owner. */
export function repositoryWasmBuildPolicyV1(cwd: string): WasmBuildPolicyV1 {
  const root = getWorkspaceRoot(), bindgen = resolveWasmBindgenBin(root), environment = wasmPackEnvironment(root, bindgen, process.env), local = resolveWorkspaceBin("wasm-pack", cwd);
  const cargo = Bun.TOML.parse(readFileSync(join(cwd, "Cargo.toml"), "utf8")) as { package?: { name?: string } };
  if (!cargo.package?.name) throw Error("WASM source owner requires an authored Cargo package name");
  return { version: 1, cwd: resolve(cwd), mode: semioBuildMode(), artifactDirectory: process.env.SEMIO_TEST_ARTIFACT_DIR ? resolve(process.env.SEMIO_TEST_ARTIFACT_DIR) : join(cwd, "dist"), buildDirectory: cargoDirectories(root).build, leaseDirectory: repoCacheDirectory(root,"agents","resource-leases"), budgetMs: buildBudgetMs(), packageName: cargo.package.name, searchPath: environment.PATH ?? "", bindgen: { command: bindgen, args: [] }, wasmPack: local ? { command: process.execPath, args: [local] } : { command: "wasm-pack", args: [] } };
}
/** 🦀️ Composes actual repository source preparation with neutral browser compiler execution. */
export async function buildRepositoryWasmWebV1(options: WasmPackWebBuildOptions): Promise<void> {
  prepareCargoWorkspaceInvocation(getWorkspaceRoot(), ["build", "--manifest-path", join(options.rsDir, "Cargo.toml")], options.rsDir);
  await buildWasmWebV1(options, repositoryWasmBuildPolicyV1(options.rsDir));
}

const EXTENSION_COMPONENT_WASM_TARGET = "wasm32-wasip2";

/** 🛡️ Explicit WASI-only link profiles; native dev and publication identity stay separate. */
export function selectComponentWasmProfile(mode: SemioBuildMode, override?: string): "wasm-dev" | "wasm-release" {
  if (mode !== "dev" && mode !== "ship") throw new Error("invalid component build mode");
  const profile = override ?? (mode === "ship" ? "wasm-release" : "wasm-dev");
  if (profile !== "wasm-dev" && profile !== "wasm-release") throw new Error("SEMIO_PLUGIN_PROFILE must be wasm-dev or wasm-release");
  return profile;
}

function parseCargoTomlStringArray(block: string, key: string): string[] {
  const match = block.match(new RegExp(`^${key}\\s*=\\s*\\[([^\\]]*)\\]`, "m"));
  if (!match) return [];
  return [...match[1]!.matchAll(/"([^"]+)"/g)].map((row) => row[1]!);
}

/** 🧩️ Reads one extension crate's Cargo identity — the crate name every extension route (`package`'s
 * `.sxt` and `describe`'s owner descriptor pair alike) builds from, its component package id, and its
 * declared `extends` host. */
export function parseExtensionCargoManifest(
  manifestPath: string,
  repoRoot: string,
): {
  readonly packageName: string;
  readonly directoryName: string;
  readonly version: string;
  readonly description: string;
  readonly componentPackageId: string;
  readonly extends: string;
  readonly contributes: readonly string[];
} {
  const text = readFileSync(manifestPath, "utf8");
  const packageName = text.match(/^name\s*=\s*"([^"]+)"/m)?.[1];
  if (!packageName) throw new Error(`missing package name in ${manifestPath}`);
  let version = text.match(/^version\s*=\s*"([^"]+)"/m)?.[1];
  if (!version && /^\s*version\.workspace\s*=\s*true/m.test(text)) {
    const rootToml = readFileSync(join(repoRoot, "Cargo.toml"), "utf8");
    version = rootToml.match(/\[workspace\.package\][\s\S]*?^version\s*=\s*"([^"]+)"/m)?.[1];
  }
  version = version ?? "0.1.0";
  const description = text.match(/^description\s*=\s*"([^"]+)"/m)?.[1] ?? packageName;
  const componentPackageId = text.match(/\[package\.metadata\.component\][\s\S]*?^package\s*=\s*"semio:([^"]+)"/m)?.[1];
  if (!componentPackageId) throw new Error(`missing [package.metadata.component].package in ${manifestPath}`);
  const semioLines: string[] = [];
  let inSemio = false;
  for (const line of text.split("\n")) {
    if (line.trim() === "[package.metadata.semio]") {
      inSemio = true;
      continue;
    }
    if (inSemio && line.startsWith("[") && line.trim() !== "[package.metadata.semio]") break;
    if (inSemio) semioLines.push(line);
  }
  const semioBlock = semioLines.join("\n");
  const extendsHost = semioBlock.match(/^extends\s*=\s*"([^"]+)"/m)?.[1] ?? "";
  const contributes = parseCargoTomlStringArray(semioBlock, "contributes");
  const directoryName = basename(resolve(dirname(manifestPath), "../.."));
  return { packageName, directoryName, version, description, componentPackageId, extends: extendsHost, contributes };
}

/** 📦 Builds a wasip2 component and writes a runtime-installable `.sxt` beside the crate (`dist/<id>.sxt` by default). */
export async function runExtensionComponentPackage(opts: { readonly rsDir: string; readonly repoRoot?: string; readonly logPrefix?: string }): Promise<string> {
  const repoRoot = opts.repoRoot ?? getWorkspaceRoot();
  const rsDir = resolve(opts.rsDir);
  const manifestPath = join(rsDir, "Cargo.toml");
  const parsed = parseExtensionCargoManifest(manifestPath, repoRoot);
  const profile = selectComponentWasmProfile(semioBuildMode(), process.env.SEMIO_PLUGIN_PROFILE);
  const logPrefix = opts.logPrefix ?? parsed.componentPackageId;
  if (runCmdStatus("cargo", ["build", "--manifest-path", manifestPath, "-p", parsed.packageName, "--target", EXTENSION_COMPONENT_WASM_TARGET, "--profile", profile], { cwd: repoRoot, budgetMs: buildBudgetMs() }) !== 0) {
    throw new Error(`extension component build failed: ${parsed.packageName}`);
  }
  const wasmArtifact = join(cargoTargetDirectory(repoRoot), EXTENSION_COMPONENT_WASM_TARGET, cargoProfileDir(profile), `${parsed.packageName.replace(/-/g, "_")}.wasm`);
  if (!existsSync(wasmArtifact)) throw new Error(`missing wasm artifact ${wasmArtifact}`);
  const componentWasm = new Uint8Array(readFileSync(wasmArtifact));
  const { packExtensionPackage } = await import("../../../💻️os/🔨️modules/🔌️plugin/🏪️store/📥️installation/🟦️.ts");
  const manifest = {
    extensionId: parsed.componentPackageId,
    directoryName: parsed.directoryName,
    label: parsed.description,
    version: parsed.version,
    extends: parsed.extends,
    capabilities: [...parsed.contributes],
    contributions: parsed.contributes,
    packageFormat: 1,
  };
  const packed = packExtensionPackage({ manifest, componentWasm });
  const outPath = join(rsDir, "dist", `${parsed.componentPackageId}.sxt`);
  mkdirSync(dirname(outPath), { recursive: true });
  writeFileSync(outPath, packed);
  console.log(`[TRACE] ${logPrefix} packaged ${outPath} (${packed.length} bytes)`);
  return outPath;
}

