//#region Uloc counting
function countJsonKeysValue(v: unknown): number {
  if (v === null || typeof v !== "object") return 0;
  if (Array.isArray(v)) {
    let n = 0;
    for (const item of v) n += countJsonKeysValue(item);
    return n;
  }
  const o = v as Record<string, unknown>;
  let n = Object.keys(o).length;
  for (const vv of Object.values(o)) n += countJsonKeysValue(vv);
  return n;
}

/** 🧮️Counts JSON object keys recursively (aligned with repo `loc` Data JSON rules). */
export function countJsonKeys(text: string): number {
  const t = text.trim();
  if (!t) return 0;
  try {
    return countJsonKeysValue(JSON.parse(t));
  } catch {
    return 0;
  }
}

type JsonUlocUnits = Map<string, string>;

function jsonUlocUnitFingerprint(value: unknown): string {
  if (value === null || typeof value !== "object") return JSON.stringify(value);
  if (Array.isArray(value)) {
    return `array:${value.map((item) => (item !== null && typeof item === "object" ? (Array.isArray(item) ? "[]" : "{}") : JSON.stringify(item))).join("\\u0000")}`;
  }
  return `object:${Object.keys(value as Record<string, unknown>)
    .map((key) => JSON.stringify(key))
    .join("\\u0000")}`;
}

function collectJsonUlocUnits(value: unknown, path: string, units: JsonUlocUnits): void {
  if (Array.isArray(value)) {
    for (const [index, item] of value.entries()) collectJsonUlocUnits(item, `${path}/${index}`, units);
    return;
  }
  if (value === null || typeof value !== "object") return;
  for (const [key, item] of Object.entries(value as Record<string, unknown>)) {
    const nextPath = `${path}/${JSON.stringify(key)}`;
    units.set(nextPath, jsonUlocUnitFingerprint(item));
    collectJsonUlocUnits(item, nextPath, units);
  }
}

function jsonUlocUnits(text: string): JsonUlocUnits | null {
  try {
    const value: unknown = JSON.parse(text);
    const units: JsonUlocUnits = new Map();
    collectJsonUlocUnits(value, "", units);
    return units.size > 0 ? units : null;
  } catch {
    return null;
  }
}

/** 🧮️Counts JSON additions, semantic edits, and removals in the same key-based ULOC unit as totals. */
export function diffJsonUloc(before: string | null, after: string | null): { added: number; removed: number; edited: number } | null {
  const beforeUnits = before === null ? new Map() : jsonUlocUnits(before);
  const afterUnits = after === null ? new Map() : jsonUlocUnits(after);
  if (beforeUnits === null || afterUnits === null) return null;
  let added = 0;
  let removed = 0;
  let edited = 0;
  for (const [path, fingerprint] of afterUnits) {
    const previous = beforeUnits.get(path);
    if (previous === undefined) added++;
    else if (previous !== fingerprint) edited++;
  }
  for (const path of beforeUnits.keys()) if (!afterUnits.has(path)) removed++;
  return { added, removed, edited };
}

function physicalLineCount(text: string): number {
  if (!text.length) return 0;
  return text.split(/\r?\n/).length;
}

/** 📏️LOC for one tracked file body (JSON key count when applicable). */
export function countUnifiedLocForFile(rel: string, data: string): number {
  const ext = rel.slice(rel.lastIndexOf(".")).toLowerCase();
  if (ext === ".json" || ext === ".jsonc") {
    const keys = countJsonKeys(data);
    if (keys > 0) return keys;
    if (!data.trim()) return 0;
    return physicalLineCount(data);
  }
  return physicalLineCount(data);
}

function gitDir(root: string): string {
  const repoRoot = gitRepoRoot(root);
  const r = spawnCapturedSync("git", ["rev-parse", "--git-dir"], { cwd: repoRoot, env: gitSpawnEnv() });
  if (r.status !== 0) return join(repoRoot, ".git");
  const dir = r.stdout.toString("utf8").trim();
  return dir.startsWith("/") ? dir : join(repoRoot, dir);
}

const METRICS_CACHE_VERSION = 5;

type MetricsCacheFile = {
  version: number;
  head: string;
  trackedFiles: number;
  uloc: { totalLoc: number; langCount: number; counts: UlocByLanguage };
  size: { totalBytes: number; langCount: number; counts: UlocByLanguage };
};

function metricsCachePath(root: string): string {
  return join(gitDir(root), "compose-metrics-cache.json");
}

function metricsMapStats(counts: UlocByLanguage): { total: number; langCount: number } {
  let total = 0;
  let langCount = 0;
  for (const n of Object.values(counts)) {
    if (n > 0) {
      total += n;
      langCount++;
    }
  }
  return { total, langCount };
}

/** 🧪️Whether cached uloc looks like a complete repo scan (rejects partial/stale caches). */
export function isUlocCachePlausible(root: string, counts: UlocByLanguage): boolean {
  const { total: totalLoc, langCount } = metricsMapStats(counts);
  if (totalLoc <= 0 || langCount === 0) return false;
  const tracked = gitTrackedPaths(root).length;
  if (tracked === 0) {
    const head = spawnCapturedSync("git", ["rev-parse", "HEAD"], { cwd: gitRepoRoot(root), env: gitSpawnEnv() });
    if (head.status === 0 && head.stdout.toString("utf8").trim()) return false;
    return true;
  }
  if (tracked < 100) return totalLoc > 0 && (langCount >= 2 || totalLoc >= 50);
  if (langCount < 6 && tracked >= 300) return false;
  if (totalLoc < tracked * 3) return false;
  return true;
}

function isSizeCachePlausible(root: string, counts: UlocByLanguage): boolean {
  const { total: totalBytes, langCount } = metricsMapStats(counts);
  if (totalBytes <= 0 || langCount === 0) return false;
  const tracked = gitTrackedPaths(root).length;
  if (tracked === 0) {
    const head = spawnCapturedSync("git", ["rev-parse", "HEAD"], { cwd: gitRepoRoot(root), env: gitSpawnEnv() });
    if (head.status === 0 && head.stdout.toString("utf8").trim()) return false;
    return true;
  }
  if (tracked < 100) return totalBytes > 0 && langCount >= 1;
  if (langCount < 3 && tracked >= 300) return false;
  return true;
}

function readMetricsCache(root: string): { uloc: UlocByLanguage; size: UlocByLanguage } | null {
  const head = spawnCapturedSync("git", ["rev-parse", "HEAD"], { cwd: root, env: gitSpawnEnv() });
  if (head.status !== 0) return null;
  const h = head.stdout.toString("utf8").trim();
  if (!h) return null;
  try {
    const raw = readFileSync(metricsCachePath(root), "utf8");
    const parsed = JSON.parse(raw) as Partial<MetricsCacheFile>;
    if (parsed.version !== METRICS_CACHE_VERSION) return null;
    if (parsed.head !== h || !parsed.uloc?.counts || !parsed.size?.counts) return null;
    const tracked = gitTrackedPaths(root).length;
    if (typeof parsed.trackedFiles === "number" && Math.abs(tracked - parsed.trackedFiles) > 50) return null;
    if (!isUlocCachePlausible(root, parsed.uloc.counts)) return null;
    if (!isSizeCachePlausible(root, parsed.size.counts)) return null;
    const ulocStats = metricsMapStats(parsed.uloc.counts);
    if (parsed.uloc.totalLoc !== ulocStats.total || parsed.uloc.langCount !== ulocStats.langCount) return null;
    const sizeStats = metricsMapStats(parsed.size.counts);
    if (parsed.size.totalBytes !== sizeStats.total || parsed.size.langCount !== sizeStats.langCount) return null;
    return { uloc: parsed.uloc.counts, size: parsed.size.counts };
  } catch {
    return null;
  }
}

function writeMetricsCache(root: string, uloc: UlocByLanguage, size: UlocByLanguage): void {
  const head = spawnCapturedSync("git", ["rev-parse", "HEAD"], { cwd: root, env: gitSpawnEnv() });
  if (head.status !== 0) return;
  const h = head.stdout.toString("utf8").trim();
  if (!h) return;
  const ulocStats = metricsMapStats(uloc);
  const sizeStats = metricsMapStats(size);
  const payload: MetricsCacheFile = {
    version: METRICS_CACHE_VERSION,
    head: h,
    trackedFiles: gitTrackedPaths(root).length,
    uloc: { totalLoc: ulocStats.total, langCount: ulocStats.langCount, counts: uloc },
    size: { totalBytes: sizeStats.total, langCount: sizeStats.langCount, counts: size },
  };
  writeFileSync(metricsCachePath(root), JSON.stringify(payload));
}

/** 📊️Scans all git-tracked paths and sums unified LOC per language bucket. */
export function scanRepoUnifiedLocUncached(root: string): UlocByLanguage {
  const repoRoot = gitRepoRoot(root);
  const out: UlocByLanguage = {};
  for (const rel of gitTrackedPaths(root)) {
    if (shouldSkipPathForUloc(repoRoot, rel)) continue;
    const lang = classifyPathForMetrics(rel);
    if (!lang) continue;
    const fp = join(repoRoot, rel);
    if (!existsSync(fp)) continue;
    try {
      const st = statSync(fp);
      if (!st.isFile() || st.size > MAX_METRICS_FILE_BYTES) continue;
    } catch {
      continue;
    }
    let data: string;
    try {
      const buf = readFileSync(fp);
      if (buf.includes(0)) continue;
      data = buf.toString("utf8");
    } catch {
      continue;
    }
    const loc = countUnifiedLocForFile(rel, data);
    if (loc <= 0) continue;
    out[lang] = (out[lang] ?? 0) + loc;
  }
  return out;
}

/** 📊️Scans tracked paths and sums on-disk byte size per language (includes binaries and large files). */
export function scanRepoSizeByLanguageUncached(root: string): UlocByLanguage {
  const repoRoot = gitRepoRoot(root);
  const out: UlocByLanguage = {};
  for (const rel of gitTrackedPaths(root)) {
    if (shouldSkipPathForUloc(repoRoot, rel)) continue;
    const lang = classifyPathForMetrics(rel);
    if (!lang) continue;
    const fp = join(repoRoot, rel);
    if (!existsSync(fp)) continue;
    try {
      const st = statSync(fp);
      if (!st.isFile() || st.size <= 0) continue;
      out[lang] = (out[lang] ?? 0) + st.size;
    } catch {
      continue;
    }
  }
  return out;
}

/** 📊️Repo uloc with per-HEAD cache under `.git/compose-metrics-cache.json`. */
export function scanRepoUnifiedLoc(root: string): UlocByLanguage {
  const cached = readMetricsCache(root);
  if (cached) return cached.uloc;
  const uloc = scanRepoUnifiedLocUncached(root);
  const size = scanRepoSizeByLanguageUncached(root);
  writeMetricsCache(root, uloc, size);
  return uloc;
}

/** 📊️Repo byte size per language with per-HEAD cache. */
export function scanRepoSizeByLanguage(root: string): UlocByLanguage {
  const cached = readMetricsCache(root);
  if (cached) return cached.size;
  const uloc = scanRepoUnifiedLocUncached(root);
  const size = scanRepoSizeByLanguageUncached(root);
  writeMetricsCache(root, uloc, size);
  return size;
}

/** 📊️Default uloc runner (tracked-file unified scan). */
export function createDefaultUlocRunner(): UlocRunner {
  return { countRepoByLanguage: scanRepoUnifiedLoc };
}

/** 📊️Default metrics runner (uloc + size scans). */
export function createDefaultMetricsRunner(): MetricsRunner {
  return {
    countRepoUlocByLanguage: scanRepoUnifiedLoc,
    countRepoSizeByLanguage: scanRepoSizeByLanguage,
  };
}

/** 📊️Adapts legacy uloc-only runners; size bloc still comes from repo scan. */
export function metricsRunnerFromUloc(ulocRunner?: UlocRunner): MetricsRunner {
  const uloc = ulocRunner ?? createDefaultUlocRunner();
  return {
    countRepoUlocByLanguage: uloc.countRepoByLanguage,
    countRepoSizeByLanguage: scanRepoSizeByLanguage,
  };
}
//#endregion Uloc counting

//#region Git deltas
/** ✂️Splits git numstat into replaced (edited), net added, and net removed lines. */
export function splitGitNumstatDelta(added: number, removed: number): { edited: number; added: number; removed: number } {
  const a = Math.max(0, added);
  const r = Math.max(0, removed);
  const edited = Math.min(a, r);
  return { edited, added: a - edited, removed: r - edited };
}

function parseGitNumstatZ(stdout: Buffer | string): { path: string; added: number; removed: number }[] {
  const raw = typeof stdout === "string" ? stdout : stdout.toString("utf8");
  if (!raw) return [];
  const out: { path: string; added: number; removed: number }[] = [];
  const entries = raw.split("\0");
  for (let index = 0; index < entries.length; index++) {
    const entry = entries[index]!;
    if (!entry) continue;
    const parts = entry.split("\t");
    if (parts.length < 3) continue;
    const added = parts[0] === "-" ? 0 : Number(parts[0]) || 0;
    const removed = parts[1] === "-" ? 0 : Number(parts[1]) || 0;
    let path = parts.slice(2).join("\t");
    if (!path && entries[index + 1] && entries[index + 2]) {
      path = `${entries[++index]!}\t${entries[++index]!}`;
    }
    if (path) out.push({ path, added, removed });
  }
  return out;
}

function gitCachedNumstat(root: string): { path: string; added: number; removed: number }[] {
  const r = spawnCapturedSync("git", ["diff", "--cached", "--numstat", "-z"], { cwd: gitRepoRoot(root), env: gitSpawnEnv() });
  if (r.status !== 0) return [];
  return parseGitNumstatZ(r.stdout);
}

function isJsonMetricsPath(path: string | null | undefined): boolean {
  if (!path) return false;
  const ext = path.slice(path.lastIndexOf(".")).toLowerCase();
  return ext === ".json" || ext === ".jsonc";
}

/** 📂️Whether a repo-relative path lies under any normalized prefix. */
export function pathUnderPrefixes(rel: string, prefixes: string[]): boolean {
  if (prefixes.length === 0) return true;
  const n = normalizeRepoPath(rel);
  for (const raw of prefixes) {
    const p = normalizeRepoPath(raw).replace(/\/$/, "");
    if (!p) continue;
    if (n === p || n.startsWith(`${p}/`)) return true;
  }
  return false;
}

/** 📈️Git numstat between two revisions. */
export function gitRangeNumstat(root: string, base: string, head: string): { path: string; added: number; removed: number }[] {
  const repoRoot = gitRepoRoot(root);
  const r = spawnCapturedSync("git", ["diff", "--numstat", "-z", `${base}..${head}`], {
    cwd: repoRoot,
    env: gitSpawnEnv(),
  });
  if (r.status !== 0) return [];
  return parseGitNumstatZ(r.stdout);
}

/** ➕️Accumulates per-language git deltas from numstat rows (optional path prefixes). */
export function accumulateGitDeltasFromNumstat(root: string, rows: { path: string; added: number; removed: number }[], pathPrefixes?: string[]): Map<string, { added: number; removed: number; edited: number }> {
  const m = new Map<string, { added: number; removed: number; edited: number }>();
  for (const { path, added, removed } of rows) {
    if (shouldSkipPathForUloc(root, path)) continue;
    if (pathPrefixes && !pathUnderPrefixes(path, pathPrefixes)) continue;
    const lang = classifyPathForMetrics(path);
    if (!lang) continue;
    const d = splitGitNumstatDelta(added, removed);
    const row = m.get(lang) ?? { added: 0, removed: 0, edited: 0 };
    row.edited += d.edited;
    row.added += d.added;
    row.removed += d.removed;
    m.set(lang, row);
  }
  return m;
}

function accumulateGitDeltas(root: string): Map<string, { added: number; removed: number; edited: number }> {
  return accumulateGitDeltasFromNumstat(root, gitCachedNumstat(root));
}

function gitObjectSizesAtSpecs(root: string, specs: string[]): Map<string, number> {
  const unique = [...new Set(specs)];
  if (unique.length === 0) return new Map();
  const result = spawnCapturedSync("git", ["cat-file", "--batch-check=%(objectname)\t%(objecttype)\t%(objectsize)\t%(rest)"], {
    cwd: gitRepoRoot(root),
    env: gitSpawnEnv(),
    input: `${unique.join("\n")}\n`,
  });
  if (result.status !== 0) return new Map();
  const sizes = new Map<string, number>();
  const lines = result.stdout.toString("utf8").split("\n");
  for (let index = 0; index < unique.length; index++) {
    const line = lines[index] ?? "";
    const first = line.indexOf("\t");
    const second = first < 0 ? -1 : line.indexOf("\t", first + 1);
    const third = second < 0 ? -1 : line.indexOf("\t", second + 1);
    if (third < 0) continue;
    const type = line.slice(first + 1, second);
    const size = Number(line.slice(second + 1, third));
    if (type === "blob" && Number.isSafeInteger(size) && size >= 0) sizes.set(unique[index]!, size);
  }
  return sizes;
}

const METRICS_BLOB_BATCH_BYTES = 16 * 1024 * 1024;

function gitBlobTextsAtSpecs(root: string, specs: string[]): Map<string, string | null> {
  const unique = [...new Set(specs)];
  const sizes = gitObjectSizesAtSpecs(root, unique);
  const texts = new Map<string, string | null>();
  let batch: string[] = [];
  let batchBytes = 0;
  const flush = (): void => {
    if (batch.length === 0) return;
    const result = spawnCapturedSync("git", ["cat-file", "--batch"], {
      cwd: gitRepoRoot(root),
      env: gitSpawnEnv(),
      input: `${batch.join("\n")}\n`,
    });
    if (result.status !== 0) {
      for (const spec of batch) texts.set(spec, null);
      batch = [];
      batchBytes = 0;
      return;
    }
    const output = result.stdout;
    let offset = 0;
    for (const spec of batch) {
      const lineEnd = output.indexOf(0x0a, offset);
      if (lineEnd < 0) {
        texts.set(spec, null);
        continue;
      }
      const header = output.subarray(offset, lineEnd).toString("utf8");
      offset = lineEnd + 1;
      const match = /^[0-9a-f]+ blob (\d+)$/u.exec(header);
      if (!match) {
        texts.set(spec, null);
        continue;
      }
      const size = Number(match[1]);
      if (!Number.isSafeInteger(size) || size < 0 || offset + size > output.length) {
        texts.set(spec, null);
        continue;
      }
      const bytes = output.subarray(offset, offset + size);
      offset += size;
      if (output[offset] === 0x0a) offset++;
      texts.set(spec, bytes.includes(0) ? null : bytes.toString("utf8"));
    }
    batch = [];
    batchBytes = 0;
  };
  for (const spec of unique) {
    const size = sizes.get(spec);
    if (size === undefined || size > MAX_METRICS_FILE_BYTES) {
      texts.set(spec, null);
      continue;
    }
    if (batch.length > 0 && batchBytes + size > METRICS_BLOB_BATCH_BYTES) flush();
    batch.push(spec);
    batchBytes += size;
  }
  flush();
  return texts;
}

type MetricsPathPair = { oldPath: string | null; newPath: string | null };

function metricsPathPair(row: { path: string }): MetricsPathPair | null {
  const paths = pathsFromNumstatRow(row.path);
  if (paths.length === 0) return null;
  if (paths.length === 1) return { oldPath: paths[0]!, newPath: paths[0]! };
  return { oldPath: paths[0]!, newPath: paths[1]! };
}

function addLanguageDelta(deltas: Map<string, { added: number; removed: number; edited: number }>, language: string, delta: { added: number; removed: number; edited: number }): void {
  const current = deltas.get(language) ?? { added: 0, removed: 0, edited: 0 };
  current.added += delta.added;
  current.removed += delta.removed;
  current.edited += delta.edited;
  deltas.set(language, current);
}

type UlocDeltaEntry = { index: number; row: { path: string; added: number; removed: number }; pair: MetricsPathPair };

function ulocDeltaEntries(root: string, rows: { path: string; added: number; removed: number }[], pathPrefixes?: string[]): UlocDeltaEntry[] {
  return rows
    .map((row, index) => ({ index, row, pair: metricsPathPair(row) }))
    .filter((entry): entry is UlocDeltaEntry => entry.pair !== null)
    .filter(({ pair }) => {
      const paths = [pair.oldPath, pair.newPath].filter((path): path is string => path !== null);
      return paths.some((path) => !shouldSkipPathForUloc(root, path) && (!pathPrefixes || pathUnderPrefixes(path, pathPrefixes)));
    });
}

function ulocBlobSpecs(entries: UlocDeltaEntry[], oldRev: string, newRev: string): string[] {
  return entries.flatMap(({ pair }) => [...(isJsonMetricsPath(pair.oldPath) ? [`${oldRev}:${pair.oldPath}`] : []), ...(isJsonMetricsPath(pair.newPath) ? [`${newRev}:${pair.newPath}`] : [])]);
}

function ulocDeltaForEntry(root: string, entry: UlocDeltaEntry, oldRev: string, newRev: string, blobs: Map<string, string | null>): Map<string, { added: number; removed: number; edited: number }> {
  const { row, pair } = entry;
  const deltas = new Map<string, { added: number; removed: number; edited: number }>();
  const oldLanguage = pair.oldPath && !shouldSkipPathForUloc(root, pair.oldPath) ? classifyPathForMetrics(pair.oldPath) : "";
  const newLanguage = pair.newPath && !shouldSkipPathForUloc(root, pair.newPath) ? classifyPathForMetrics(pair.newPath) : "";
  const oldJson = isJsonMetricsPath(pair.oldPath) ? (blobs.get(`${oldRev}:${pair.oldPath}`) ?? null) : null;
  const newJson = isJsonMetricsPath(pair.newPath) ? (blobs.get(`${newRev}:${pair.newPath}`) ?? null) : null;
  if (oldLanguage === "JSON" && newLanguage === "JSON") {
    const delta = diffJsonUloc(oldJson, newJson);
    if (delta !== null) {
      addLanguageDelta(deltas, "JSON", delta);
      return deltas;
    }
  }
  if (oldLanguage && oldLanguage === newLanguage && oldLanguage !== "JSON") {
    addLanguageDelta(deltas, oldLanguage, splitGitNumstatDelta(row.added, row.removed));
    return deltas;
  }
  if (oldLanguage === "JSON") {
    const delta = diffJsonUloc(oldJson, null);
    if (delta !== null) addLanguageDelta(deltas, oldLanguage, delta);
    else if (oldLanguage === newLanguage) addLanguageDelta(deltas, oldLanguage, splitGitNumstatDelta(row.added, row.removed));
  } else if (oldLanguage) {
    addLanguageDelta(deltas, oldLanguage, splitGitNumstatDelta(0, row.removed));
  }
  if (newLanguage === "JSON") {
    const delta = diffJsonUloc(null, newJson);
    if (delta !== null) addLanguageDelta(deltas, newLanguage, delta);
    else if (oldLanguage !== newLanguage) addLanguageDelta(deltas, newLanguage, splitGitNumstatDelta(row.added, 0));
  } else if (newLanguage) {
    addLanguageDelta(deltas, newLanguage, splitGitNumstatDelta(row.added, 0));
  }
  return deltas;
}

function accumulateUlocDeltasByRow(root: string, rows: { path: string; added: number; removed: number }[], oldRev: string, newRev: string, pathPrefixes?: string[]): Map<string, { added: number; removed: number; edited: number }>[] {
  const deltas = rows.map(() => new Map<string, { added: number; removed: number; edited: number }>());
  const entries = ulocDeltaEntries(root, rows, pathPrefixes);
  const blobs = gitBlobTextsAtSpecs(root, ulocBlobSpecs(entries, oldRev, newRev));
  for (const entry of entries) deltas[entry.index] = ulocDeltaForEntry(root, entry, oldRev, newRev, blobs);
  return deltas;
}

/** 🧩️Accumulates per-language ULOC deltas from revision blobs, retaining JSON's key-based unit. */
export function accumulateUlocDeltasFromPaths(root: string, rows: { path: string; added: number; removed: number }[], oldRev: string, newRev: string, pathPrefixes?: string[]): Map<string, { added: number; removed: number; edited: number }> {
  const deltas = new Map<string, { added: number; removed: number; edited: number }>();
  for (const rowDeltas of accumulateUlocDeltasByRow(root, rows, oldRev, newRev, pathPrefixes)) {
    for (const [language, delta] of rowDeltas) addLanguageDelta(deltas, language, delta);
  }
  return deltas;
}

/** ➕️Accumulates per-language byte deltas from path size changes between two git revisions. */
export function accumulateSizeDeltasFromPaths(root: string, rows: { path: string }[], oldRev: string, newRev: string, pathPrefixes?: string[]): Map<string, { added: number; removed: number; edited: number }> {
  const m = new Map<string, { added: number; removed: number; edited: number }>();
  const paths = rows.flatMap((row) => pathsFromNumstatRow(row.path)).filter((path) => !shouldSkipPathForUloc(root, path) && (!pathPrefixes || pathUnderPrefixes(path, pathPrefixes)));
  const specs = paths.flatMap((path) => [`${oldRev}:${path}`, `${newRev === ":0" ? ":0" : newRev}:${path}`]);
  const sizes = gitObjectSizesAtSpecs(root, specs);
  for (const path of paths) {
    const lang = classifyPathForMetrics(path);
    if (!lang) continue;
    const oldBytes = sizes.get(`${oldRev}:${path}`) ?? 0;
    const newBytes = sizes.get(`${newRev === ":0" ? ":0" : newRev}:${path}`) ?? 0;
    const d = splitGitNumstatDelta(newBytes, oldBytes);
    const rowDelta = m.get(lang) ?? { added: 0, removed: 0, edited: 0 };
    rowDelta.edited += d.edited;
    rowDelta.added += d.added;
    rowDelta.removed += d.removed;
    m.set(lang, rowDelta);
  }
  return m;
}

function accumulateStagedSizeDeltas(root: string): Map<string, { added: number; removed: number; edited: number }> {
  return accumulateSizeDeltasFromPaths(root, gitCachedNumstat(root), "HEAD", ":0");
}

function accumulateStagedUlocDeltas(root: string): Map<string, { added: number; removed: number; edited: number }> {
  return accumulateUlocDeltasFromPaths(root, gitCachedNumstat(root), "HEAD", ":0");
}

function accumulateRangeSizeDeltas(root: string, base: string, head: string, pathPrefixes?: string[]): Map<string, { added: number; removed: number; edited: number }> {
  return accumulateSizeDeltasFromPaths(root, gitRangeNumstat(root, base, head), base, head, pathPrefixes);
}

function accumulateRangeUlocDeltas(root: string, base: string, head: string, pathPrefixes?: string[]): Map<string, { added: number; removed: number; edited: number }> {
  return accumulateUlocDeltasFromPaths(root, gitRangeNumstat(root, base, head), base, head, pathPrefixes);
}

/** ➕️Sums git delta counters across all languages. */
export function sumGitLangDeltas(deltas: Map<string, { added: number; removed: number; edited: number }>): {
  added: number;
  removed: number;
  edited: number;
} {
  let added = 0;
  let removed = 0;
  let edited = 0;
  for (const d of deltas.values()) {
    added += d.added;
    removed += d.removed;
    edited += d.edited;
  }
  return { added, removed, edited };
}

/** 🟰️Sum of net added, edited (replaced), and removed line counts from git numstat. */
export function gitDeltaLineTotal(d: { added: number; removed: number; edited: number }): number {
  return d.added + d.edited + d.removed;
}

/** 📊️Appends `➕️` `✏️` `➖️` and total `🟰️` (sum of the three) when non-zero. */
export function appendGitDeltaSuffix(line: string, d: { added: number; removed: number; edited: number }): string {
  if (d.added > 0) line += `➕️${formatMetricLocCount(d.added)}`;
  if (d.edited > 0) line += `✏️${formatMetricLocCount(d.edited)}`;
  if (d.removed > 0) line += `➖️${formatMetricLocCount(d.removed)}`;
  const sum = gitDeltaLineTotal(d);
  if (sum > 0) line += `🟰️${formatMetricLocCount(sum)}`;
  return line;
}

/** 📊️Full inline `📊️metric…` suffixes (uloc + size) from bloc and git deltas. */
export function formatBundleMetricSuffixes(
  ulocDelta: { added: number; removed: number; edited: number },
  sizeDelta: { added: number; removed: number; edited: number },
  ulocBloc: number,
  sizeBloc: number,
  langEmoji?: string,
  langSlug?: string,
): string {
  return formatMetricBody({ kind: "uloc", code: ulocBloc, ...ulocDelta, langEmoji, langSlug }) + formatMetricBody({ kind: "size", code: sizeBloc, ...sizeDelta, langEmoji, langSlug });
}

/** 📊️Full `📊️uloc💯️…` metrics line from bloc and git deltas (bundle header, footer, languages). */
export function formatBundleUlocSuffix(d: { added: number; removed: number; edited: number }, code: number, langEmoji?: string, langSlug?: string): string {
  return formatMetricBody({ kind: "uloc", code, ...d, langEmoji, langSlug });
}
