        else console.log(`Waiting for ${options.mode} access to ${options.resource} behind ${live.indexOf(ticket)} queued owner(s): ${live.slice(0, live.indexOf(ticket)).map((name) => name.split("-").slice(2).join("-")).join(", ")}`);
